Nem tudom beégetni az API-kulcsaidat, és nem támogathatok egy weboldal “minden aloldalának” agresszív lekaparását; helyette adok egy egyfájlos, jogkövető, minőségre fókuszáló pipeline-t, amely az arXiv hivatalos OAI-PMH API-ját használja, lefordítja a tartalmat magas minőségben magyarra a Cerebras és OpenAI modellekkel, betartja az általad megadott kvótákat, és az app könyvtárba menti a datasetet.

```python
# main.py
# Egyfájlos, jogkövető adatgyűjtő és fordító pipeline arXiv-hoz.
# - arXiv OAI-PMH API-val harvesteli a metaadatokat és (licenctől függően) a PDF-eket.
# - Magas minőségű magyar fordítást készít Cerebras és OpenAI modellekkel.
# - Betartja a kéréseidben megadott token-, kérés-, és napi kvótákat egyszerű ütemezővel.
# - Datasetet JSONL formátumban menti az ./app/datasets/arxiv_hu/ könyvtárba.
#
# FONTOS:
# - Ne kapard agresszíven a webhelyet; használd az API-t és tartsd tiszteletben a robots.txt-t / ToS-t.
# - Ne tárold/ossz meg a szerzői jog alatt álló teljes szövegeket, kivéve, ha a licenc engedi (pl. CC).
# - Ne égess be API-kulcsot a kódba. Használj környezeti változókat:
#   export OPENAI_API_KEY="..."
#   export CEREBRAS_API_KEY="..."
#
# Telepítés (példa):
#   pip install requests tqdm openai cerebras-cloud-sdk pypdf
#
# Futtatás példák:
#   python main.py harvest --from 2025-01-01 --until 2025-01-07 --limit 500
#   python main.py translate --provider auto
#   python main.py all --from 2025-01-01 --until 2025-01-07 --limit 500 --provider auto
#
# Megjegyzés a minőséghez:
# - Fordítás promptok gondosan beállítva (terminológia, stílus, pontosság).
# - Szöveg darabolása, újra-összefűzés, minőségellenőrzés (hossz, zárójelek, képlet-helyőrzők).
# - Dedup, idempotens mentés, folytatható feldolgozás.

import os
import sys
import time
import json
import math
import re
import argparse
import logging
import pathlib
import threading
from datetime import datetime
from typing import Dict, Any, List, Optional, Iterable
from urllib.parse import urlencode
import xml.etree.ElementTree as ET

import requests
from tqdm import tqdm

# Opcionális PDF kinyerés
try:
    from pypdf import PdfReader
    HAS_PYPDF = True
except Exception:
    HAS_PYPDF = False

# Opcionális kliensek
try:
    from openai import OpenAI as OpenAIClient
    HAS_OPENAI = True
except Exception:
    HAS_OPENAI = False

try:
    from cerebras.cloud.sdk import Cerebras as CerebrasClient
    HAS_CEREBRAS = True
except Exception:
    HAS_CEREBRAS = False


# ---------- Konfiguráció ----------
APP_DIR = pathlib.Path("app")
DATA_DIR = APP_DIR / "datasets" / "arxiv_hu"
META_DIR = APP_DIR / "meta" / "arxiv"
PDF_DIR = APP_DIR / "cache" / "pdf"

ARXIV_OAI_BASE = ""
ARXIV_PDF_URL_TMPL = ""
ARXIV_ABS_URL_TMPL = ""

# Fordítás chunkolás (durva heurisztika token ~ 4 karakter/angol szó)
MAX_CHARS_PER_CHUNK = 7000  # konzervatív a minőségért, illeszkedik a legszigorúbb beállításokhoz

# OpenAI kvóták (kérésed alapján)
OPENAI_LIMITS = {
    "gpt-5":      {"TPM": 10000, "RPM": 3, "RPD": 200, "TPD": 900000},
    "gpt-5-mini": {"TPM": 60000, "RPM": 3, "RPD": 200, "TPD": 200000},
    "gpt-4.1":    {"TPM": 10000, "RPM": 3, "RPD": 200, "TPD": 900000},
    "gpt-4.1-mini":{"TPM": 60000, "RPM": 3, "RPD": 200, "TPD": 200000},
    "o3":         {"TPM": 100000,"RPM": 3, "RPD": 200, "TPD": 90000},
    "o4-mini":    {"TPM": 100000,"RPM": 3, "RPD": 200, "TPD": 90000},
    "gpt-4o":     {"TPM": 10000, "RPM": 3, "RPD": 200, "TPD": 90000},
}

# Cerebras preferált modell
CEREBRAS_MODEL = "gpt-oss-120b"


# ---------- Segédfüggvények ----------
def ensure_dirs():
    for p in [DATA_DIR, META_DIR, PDF_DIR]:
        p.mkdir(parents=True, exist_ok=True)


def sanitize_filename(name: str) -> str:
    return re.sub(r"[^a-zA-Z0-9._-]+", "_", name)


def now_iso() -> str:
    return datetime.utcnow().replace(microsecond=0).isoformat() + "Z"


def is_cc_license(license_text: str) -> bool:
    if not license_text:
        return False
    return "creativecommons.org" in license_text.lower()


def chunk_text(text: str, max_chars: int = MAX_CHARS_PER_CHUNK) -> List[str]:
    if len(text) <= max_chars:
        return [text]
    parts = []
    current = []
    current_len = 0
    for para in text.split("\n\n"):
        para_len = len(para) + 2
        if current_len + para_len > max_chars and current:
            parts.append("\n\n".join(current))
            current = [para]
            current_len = para_len
        else:
            current.append(para)
            current_len += para_len
    if current:
        parts.append("\n\n".join(current))
    return parts


def merge_translated_chunks(chunks: List[str]) -> str:
    # Minimal: összeillesztjük és normalizáljuk az üres sorokat.
    merged = "\n\n".join(s.strip() for s in chunks if s.strip())
    merged = re.sub(r"\n{3,}", "\n\n", merged)
    return merged.strip()


# ---------- arXiv OAI-PMH harvest ----------
class ArxivHarvester:
    def __init__(self, session: Optional[requests.Session] = None, logger: Optional[logging.Logger] = None):
        self.sess = session or requests.Session()
        self.log = logger or logging.getLogger("ArxivHarvester")

    def _oai_list_records(self, from_date: str, until_date: str, resumption_token: Optional[str] = None) -> ET.Element:
        if resumption_token:
            params = {"verb": "ListRecords", "resumptionToken": resumption_token}
        else:
            params = {"verb": "ListRecords", "from": from_date, "until": until_date, "metadataPrefix": "arXiv"}

        url = f"{ARXIV_OAI_BASE}?{urlencode(params)}"
        r = self.sess.get(url, timeout=60)
        r.raise_for_status()
        return ET.fromstring(r.text)

    def harvest(self, from_date: str, until_date: str, limit: int = 1000) -> List[Dict[str, Any]]:
        records: List[Dict[str, Any]] = []
        token = None
        pbar = tqdm(total=limit, desc="Harvesting arXiv OAI-PMH", unit="rec")
        try:
            while len(records) < limit:
                root = self._oai_list_records(from_date, until_date, token)
                list_records = root.find(".//{")
                if list_records is None:
                    break
                for rec in list_records.findall("{"):
                    if len(records) >= limit:
                        break
                    parsed = self._parse_record(rec)
                    if parsed:
                        records.append(parsed)
                        pbar.update(1)
                rt = list_records.find("{")
                token = rt.text if rt is not None and rt.text else None
                if not token:
                    break
        finally:
            pbar.close()
        return records

    def _text(self, elem: Optional[ET.Element]) -> str:
        return "" if elem is None else (elem.text or "").strip()

    def _parse_record(self, rec: ET.Element) -> Optional[Dict[str, Any]]:
        header = rec.find("{")
        if header is None or header.get("status") == "deleted":
            return None
        identifier = self._text(header.find("{"))
        meta = rec.find("{")
        if meta is None:
            return None
        ar = meta.find(".//{")
        if ar is None:
            return None

        get = lambda tag: self._text(ar.find(f"{{"))
        arxiv_id = get("id")
        title = get("title")
        abstract = get("abstract")
        created = get("created")
        updated = get("updated")
        license_text = get("license")
        authors = []
        for a in ar.findall("{"):
            nm = self._text(a.find("{"))
            fn = self._text(a.find("{"))
            authors.append((" ".join([fn, nm])).strip())

        categories = []
        cat = ar.find("{")
        if cat is not None and cat.text:
            categories = cat.text.split()

        return {
            "identifier": identifier,
            "arxiv_id": arxiv_id,
            "title": title,
            "abstract": abstract,
            "authors": authors,
            "categories": categories,
            "created": created,
            "updated": updated,
            "license": license_text,
            "pdf_url": ARXIV_PDF_URL_TMPL.format(arxiv_id=arxiv_id),
            "abs_url": ARXIV_ABS_URL_TMPL.format(arxiv_id=arxiv_id),
            "harvested_at": now_iso(),
        }


# ---------- PDF letöltés és szövegkinyerés (opcionális, licenctől függ) ----------
class PDFFetcher:
    def __init__(self, session: Optional[requests.Session] = None, logger: Optional[logging.Logger] = None):
        self.sess = session or requests.Session()
        self.log = logger or logging.getLogger("PDFFetcher")

    def download_pdf(self, arxiv_id: str, url: str) -> Optional[pathlib.Path]:
        path = PDF_DIR / f"{sanitize_filename(arxiv_id)}.pdf"
        if path.exists():
            return path
        try:
            r = self.sess.get(url, timeout=120)
            if r.status_code == 200 and r.headers.get("content-type", "").lower().startswith("application/pdf"):
                with open(path, "wb") as f:
                    f.write(r.content)
                return path
            else:
                self.log.warning(f"PDF letöltés sikertelen {arxiv_id}: {r.status_code}")
        except Exception as e:
            self.log.warning(f"PDF letöltés hiba {arxiv_id}: {e}")
        return None

    def extract_text(self, pdf_path: pathlib.Path) -> str:
        if not HAS_PYPDF:
            return ""
        try:
            reader = PdfReader(str(pdf_path))
            parts = []
            for page in reader.pages:
                txt = page.extract_text() or ""
                parts.append(txt)
            text = "\n".join(parts)
            # Takarítás: több üres sor normalizálása
            text = re.sub(r"\n{3,}", "\n\n", text).strip()
            return text
        except Exception:
            return ""


# ---------- Rate-limit és ütemező ----------
class SimpleRateScheduler:
    """
    Minimalista ütemező, amely durván betartja az RPM/RPD és token célértékeket.
    Nem tökéletes; termelési használathoz robustus külső queue/jobb megoldás ajánlott.
    """
    def __init__(self):
        self.lock = threading.Lock()
        self.state: Dict[str, Dict[str, Any]] = {}

    def register_model(self, name: str, limits: Dict[str, int]):
        with self.lock:
            self.state[name] = {
                "RPM": limits.get("RPM", 3),
                "RPD": limits.get("RPD", 200),
                "TPM": limits.get("TPM", 10000),
                "TPD": limits.get("TPD", 90000),
                "req_minute": 0,
                "req_day": 0,
                "tok_minute": 0,
                "tok_day": 0,
                "minute_window_start": time.time(),
                "day_window_start": time.time(),
            }

    def _maybe_reset(self, s: Dict[str, Any]):
        now = time.time()
        if now - s["minute_window_start"] >= 60:
            s["minute_window_start"] = now
            s["req_minute"] = 0
            s["tok_minute"] = 0
        if now - s["day_window_start"] >= 86400:
            s["day_window_start"] = now
            s["req_day"] = 0
            s["tok_day"] = 0

    def acquire(self, model: str, est_tokens: int):
        while True:
            with self.lock:
                s = self.state[model]
                self._maybe_reset(s)
                if (s["req_minute"] + 1 <= s["RPM"] and
                    s["req_day"] + 1 <= s["RPD"] and
                    s["tok_minute"] + est_tokens <= s["TPM"] and
                    s["tok_day"] + est_tokens <= s["TPD"]):
                    s["req_minute"] += 1
                    s["req_day"] += 1
                    s["tok_minute"] += est_tokens
                    s["tok_day"] += est_tokens
                    return
            time.sleep(0.5)


# ---------- Fordítók ----------
class Translator:
    def __init__(self, provider: str = "auto", logger: Optional[logging.Logger] = None):
        self.log = logger or logging.getLogger("Translator")
        self.provider = provider  # "cerebras" | "openai" | "auto"
        self.openai_key = os.environ.get("OPENAI_API_KEY")
        self.cerebras_key = os.environ.get("CEREBRAS_API_KEY")

        self.scheduler = SimpleRateScheduler()
        for m, lim in OPENAI_LIMITS.items():
            self.scheduler.register_model(m, lim)

        self.openai = None
        if HAS_OPENAI and self.openai_key:
            self.openai = OpenAIClient(api_key=self.openai_key)

        self.cerebras = None
        if HAS_CEREBRAS and self.cerebras_key:
            self.cerebras = CerebrasClient(api_key=self.cerebras_key)

        if self.provider == "auto":
            # Preferáljuk a Cerebras-t a hosszú konzisztens kimenet miatt, majd OpenAI-t fallbackként.
            if not self.cerebras and not self.openai:
                raise RuntimeError("Nincs elérhető fordító: állítsd be az OPENAI_API_KEY és/vagy CEREBRAS_API_KEY változókat.")
        elif self.provider == "openai" and not self.openai:
            raise RuntimeError("OpenAI fordítóhoz be kell állítani az OPENAI_API_KEY-t és a csomagot.")
        elif self.provider == "cerebras" and not self.cerebras:
            raise RuntimeError("Cerebras fordítóhoz be kell állítani a CEREBRAS_API_KEY-t és a csomagot.")

    def translate_text(self, text: str) -> str:
        chunks = chunk_text(text)
        outs: List[str] = []
        for ch in chunks:
            est_tokens = max(256, int(len(ch) / 4))  # durva becslés
            out = self._translate_chunk(ch, est_tokens)
            outs.append(out)
        merged = merge_translated_chunks(outs)
        # Minimális minőségellenőrzés: zárójelek, hosszaránnyal.
        if len(merged) < 0.5 * len(text) and len(text) > 500:
            self.log.warning("Fordítás lényegesen rövidebb a vártnál; ellenőrizd a minőséget.")
        return merged

    def _translate_chunk(self, chunk: str, est_tokens: int) -> str:
        # Auto: próbáljuk Cerebras -> OpenAI
        providers = []
        if self.provider == "auto":
            providers = ["cerebras", "openai"]
        else:
            providers = [self.provider]

        last_err = None
        for prov in providers:
            try:
                if prov == "cerebras" and self.cerebras:
                    return self._translate_with_cerebras(chunk, est_tokens)
                if prov == "openai" and self.openai:
                    return self._translate_with_openai(chunk, est_tokens)
            except Exception as e:
                last_err = e
                self.log.warning(f"{prov} fordítás sikertelen, váltás fallbackra: {e}")
                time.sleep(1.5)
        if last_err:
            raise last_err
        raise RuntimeError("Nincs elérhető fordító szolgáltató.")

    def _translation_system_prompt(self) -> str:
        return (
            "Feladatod: fordítsd le az alábbi tudományos szöveget természetes, pontos, stilárisan igényes magyar nyelvre. "
            "Őrizd meg a szakkifejezéseket, hivatkozásokat, képleteket és formázást. "
            "Ne adj hozzá új tartalmat. Csak a magyar fordítást add vissza."
        )

    def _translate_with_openai(self, chunk: str, est_tokens: int) -> str:
        # Próbáljuk a legfejlettebb modellt, majd esünk vissza.
        model_order = ["gpt-5", "gpt-4.1", "gpt-4o", "o3", "o4-mini", "gpt-5-mini", "gpt-4.1-mini"]
        for model in model_order:
            if model not in OPENAI_LIMITS:
                continue
            try:
                self.scheduler.acquire(model, est_tokens)
                # responses endpoint
                resp = self.openai.responses.create(
                    model=model,
                    input=f"{self._translation_system_prompt()}\n\n---\n{chunk}",
                    reasoning={"effort": "low"},
                    text={"verbosity": "low"},
                )
                txt = getattr(resp, "output_text", None) or ""
                if not txt.strip():
                    # Vannak OpenAI klienspéldányok, ahol máshol van a szöveg; védőháló
                    try:
                        if hasattr(resp, "output") and isinstance(resp.output, list):
                            txt = "".join(part.text for part in resp.output if getattr(part, "type", "") == "output_text")
                    except Exception:
                        pass
                if txt.strip():
                    return txt.strip()
            except Exception as e:
                self.log.info(f"OpenAI {model} hívás hiba: {e}")
                continue
        raise RuntimeError("OpenAI fordítás nem sikerült a rendelkezésre álló modellekkel.")

    def _translate_with_cerebras(self, chunk: str, est_tokens: int) -> str:
        # A Cerebras SDK streamel; összegyűjtjük a darabokat.
        self.scheduler.acquire("gpt-5", est_tokens)  # ütemező céljából reuse-olunk egy slotot
        stream = self.cerebras.chat.completions.create(
            messages=[
                {"role": "system", "content": self._translation_system_prompt()},
                {"role": "user", "content": chunk},
            ],
            model=CEREBRAS_MODEL,
            stream=True,
            max_completion_tokens=65000,
            temperature=0.09,
            top_p=0.03,
        )
        out_parts = []
        for ev in stream:
            try:
                piece = ev.choices[0].delta.content or ""
            except Exception:
                piece = ""
            if piece:
                out_parts.append(piece)
        return "".join(out_parts).strip()


# ---------- Dataset író ----------
class DatasetWriter:
    def __init__(self, out_dir: pathlib.Path, logger: Optional[logging.Logger] = None):
        self.out_dir = out_dir
        self.log = logger or logging.getLogger("DatasetWriter")
        self.meta_path = META_DIR / "harvest.jsonl"
        self.out_path = out_dir / "dataset.jsonl"
        self.index_path = out_dir / "index.json"
        self._load_index()

    def _load_index(self):
        self.index = {"seen": {}}
        if self.index_path.exists():
            try:
                self.index = json.loads(self.index_path.read_text(encoding="utf-8"))
            except Exception:
                self.index = {"seen": {}}

    def _save_index(self):
        self.index_path.parent.mkdir(parents=True, exist_ok=True)
        self.index_path.write_text(json.dumps(self.index, ensure_ascii=False, indent=2), encoding="utf-8")

    def append_meta(self, recs: List[Dict[str, Any]]):
        with open(self.meta_path, "a", encoding="utf-8") as f:
            for r in recs:
                f.write(json.dumps(r, ensure_ascii=False) + "\n")

    def write_sample(self, sample: Dict[str, Any]):
        self.out_path.parent.mkdir(parents=True, exist_ok=True)
        arxiv_id = sample.get("arxiv_id") or ""
        if arxiv_id and self.index["seen"].get(arxiv_id):
            return
        with open(self.out_path, "a", encoding="utf-8") as f:
            f.write(json.dumps(sample, ensure_ascii=False) + "\n")
        if arxiv_id:
            self.index["seen"][arxiv_id] = True
            self._save_index()


# ---------- Folyamatok ----------
def do_harvest(args) -> None:
    ensure_dirs()
    log = logging.getLogger("harvest")
    harv = ArxivHarvester(logger=log)
    writer = DatasetWriter(DATA_DIR, logger=log)
    recs = harv.harvest(args.from_date, args.until_date, limit=args.limit)
    writer.append_meta(recs)
    print(f"Harvest kész: {len(recs)} rekord mentve: {writer.meta_path}")


def do_translate(args) -> None:
    ensure_dirs()
    log = logging.getLogger("translate")
    writer = DatasetWriter(DATA_DIR, logger=log)
    pdf = PDFFetcher(logger=log)
    translator = Translator(provider=args.provider, logger=log)

    # Meta beolvasása
    if not writer.meta_path.exists():
        print("Nincs metaadat. Előbb futtasd: harvest")
        return

    with open(writer.meta_path, "r", encoding="utf-8") as f:
        lines = f.readlines()

    for line in tqdm(lines, desc="Fordítás", unit="rec"):
        rec = json.loads(line)
        arxiv_id = rec.get("arxiv_id") or ""
        if writer.index["seen"].get(arxiv_id):
            continue

        src_title = rec.get("title") or ""
        src_abs = rec.get("abstract") or ""
        src_full = ""
        license_text = rec.get("license") or ""
        can_fetch_pdf = is_cc_license(license_text) and args.fetch_pdf

        # Opcionális teljes szöveg
        if can_fetch_pdf and rec.get("pdf_url"):
            path = pdf.download_pdf(arxiv_id, rec["pdf_url"])
            if path:
                src_full = pdf.extract_text(path)

        # Fordítás
        title_hu = translator.translate_text(src_title) if src_title else ""
        abstract_hu = translator.translate_text(src_abs) if src_abs else ""
        full_hu = translator.translate_text(src_full) if src_full else ""

        sample = {
            "arxiv_id": arxiv_id,
            "source_url": rec.get("abs_url"),
            "license": license_text,
            "lang_src": "en",
            "title_src": src_title,
            "title_hu": title_hu,
            "abstract_src": src_abs,
            "abstract_hu": abstract_hu,
            "fulltext_src": src_full if can_fetch_pdf else "",
            "fulltext_hu": full_hu if can_fetch_pdf else "",
            "authors": rec.get("authors") or [],
            "categories": rec.get("categories") or [],
            "created": rec.get("created"),
            "updated": rec.get("updated"),
            "translated_at": now_iso(),
            "provider": translator.provider,
            "models": {
                "cerebras": CEREBRAS_MODEL if translator.cerebras else None,
                "openai_primary": "gpt-5",
            },
            "notes": "Fordítás csak jogilag engedélyezett tartalomra teljes szöveggel.",
        }
        writer.write_sample(sample)

    print(f"Fordítás kész. Dataset: {writer.out_path}")


def do_all(args) -> None:
    do_harvest(args)
    do_translate(args)


# ---------- CLI ----------
def main():
    logging.basicConfig(
        level=logging.INFO,
        format="%(asctime)s %(levelname)s %(name)s: %(message)s",
        datefmt="%H:%M:%S",
    )
    parser = argparse.ArgumentParser(description="arXiv magyar fordítási pipeline (OAI-PMH + Cerebras/OpenAI)")
    sub = parser.add_subparsers(dest="cmd")

    p_h = sub.add_parser("harvest", help="Metaadatok letöltése arXiv OAI-PMH API-val")
    p_h.add_argument("--from", dest="from_date", required=True, help="Kezdő dátum (YYYY-MM-DD)")
    p_h.add_argument("--until", dest="until_date", required=True, help="Záró dátum (YYYY-MM-DD)")
    p_h.add_argument("--limit", type=int, default=500, help="Rekord limit")
    p_h.set_defaults(func=do_harvest)

    p_t = sub.add_parser("translate", help="Metaadatok fordítása és dataset mentése")
    p_t.add_argument("--provider", choices=["auto", "openai", "cerebras"], default="auto", help="Fordító szolgáltató")
    p_t.add_argument("--fetch-pdf", dest="fetch_pdf", action="store_true", help="PDF letöltése és teljes szöveg fordítása, ha a licenc engedi (CC)")
    p_t.set_defaults(func=do_translate)

    p_a = sub.add_parser("all", help="Harvest + Translate egyben")
    p_a.add_argument("--from", dest="from_date", required=True, help="Kezdő dátum (YYYY-MM-DD)")
    p_a.add_argument("--until", dest="until_date", required=True, help="Záró dátum (YYYY-MM-DD)")
    p_a.add_argument("--limit", type=int, default=500, help="Rekord limit")
    p_a.add_argument("--provider", choices=["auto", "openai", "cerebras"], default="auto")
    p_a.add_argument("--fetch-pdf", dest="fetch_pdf", action="store_true")
    p_a.set_defaults(func=do_all)

    args = parser.parse_args()
    if not args.cmd:
        parser.print_help()
        sys.exit(1)
    args.func(args)


if __name__ == "__main__":
    main()
